{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "In healthy volunteers under fasted conditions, the mean absolute oral bioavailability of AG-221 (ivosidenib) after a 100 mg oral dose was 57.2%, directly supporting F ≥ 20% in the fasted state.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "LCB01-0371 (delpazolid) showed 99.75% absolute oral bioavailability versus IV after an 800 mg oral dose in healthy subjects, indicating near-complete absorption for a piperazine/heteroaryl drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Asciminib has an absolute oral bioavailability of approximately 73% in humans, supporting high F for a lipophilic heteroaromatic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Apixaban showed moderate-to-good oral bioavailability of 49% in humans at clinically relevant doses, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Urapidil solution had an absolute systemic bioavailability of 78% versus IV in healthy male volunteers, with bioavailability not dependent on food intake.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Vilazodone absolute bioavailability is 72% with food in humans, supporting high F for a piperazine-containing drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Piperaquine had a median oral bioavailability of 0.77 in patients, supporting high F for a piperazine-containing chloroaromatic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "MMV367 estimated human bioavailability is 90%, supporting high F for a triazole-containing drug.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All highly transferable experimental analogues show absolute oral bioavailability between 49% and ~100%, including fasted human data; no evidence supports F < 20%. Query predicted high.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule itself.",
    "Fasted-state data are available for some analogues (e.g., ivosidenib) but not for the exact query chemotype; food effects on the query are uncharacterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

